# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">STATİK VE KİNETİK SÜRTÜNME KUVVETLERİNİN KARŞILAŞTIRILMASI</text>\n  <rect x="35" y="50" width="300" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Statik Sürtünme Kuvveti (fs)</text>\n  <text x="50" y="103" font-size="11" fill="#334155">• Duran cismi harekete geçirmeye</text>\n  <text x="60" y="120" font-size="10.5" fill="#475569">çalışan kuvvete karşı koyar.</text>\n  <text x="50" y="143" font-size="11" fill="#334155">• Değişken değerlidir: Cisim dururken</text>\n  <text x="60" y="160" font-size="10.5" font-weight="bold" fill="#1e40af">F_uygulanan &lt;= fs,max ise fs = F_uygulanan</text>\n  <text x="50" y="185" font-size="11" fill="#334155">• Maksimum (Eşik) Değeri:</text>\n  <text x="60" y="205" font-size="12" font-weight="bold" fill="#1d4ed8">fs,max = ks · N</text>\n  <rect x="365" y="50" width="300" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Kinetik Sürtünme Kuvveti (fk)</text>\n  <text x="380" y="103" font-size="11" fill="#334155">• Hareket halindeki (kayan) cisme</text>\n  <text x="390" y="120" font-size="10.5" fill="#475569">kayma yönüne zıt yönde etki eder.</text>\n  <text x="380" y="143" font-size="11" fill="#334155">• Sabit değerlidir (hız büyüklüğünden</text>\n  <text x="390" y="160" font-size="10.5" fill="#475569">bağımsızdır):</text>\n  <text x="390" y="182" font-size="12" font-weight="bold" fill="#b91c1c">fk = kk · N</text>\n  <text x="380" y="210" font-size="11" font-weight="bold" fill="#991b1b">Aynı yüzey için: ks &gt; kk ve fs,max &gt; fk</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#1e293b">SÜRTÜNME KUVVETİ - UYGULANAN KUVVET (f_sürtünme - F) GRAFİĞİ</text>\n  <line x1="80" y1="215" x2="430" y2="215" stroke="#334155" stroke-width="2"/>\n  <line x1="80" y1="215" x2="80" y2="45" stroke="#334155" stroke-width="2"/>\n  <text x="70" y="48" text-anchor="end" font-size="11" font-weight="bold" fill="#1e293b">f_sürtünme (N)</text>\n  <text x="435" y="219" font-size="11" font-weight="bold" fill="#1e293b">F_uygulanan (N)</text>\n  <line x1="80" y1="215" x2="220" y2="75" stroke="#2563eb" stroke-width="3"/>\n  <line x1="220" y1="75" x2="235" y2="110" stroke="#dc2626" stroke-width="2.5" stroke-dasharray="4,2"/>\n  <line x1="235" y1="110" x2="400" y2="110" stroke="#16a34a" stroke-width="3"/>\n  <line x1="80" y1="75" x2="220" y2="75" stroke="#94a3b8" stroke-dasharray="4,4"/>\n  <line x1="80" y1="110" x2="235" y2="110" stroke="#94a3b8" stroke-dasharray="4,4"/>\n  <line x1="220" y1="75" x2="220" y2="215" stroke="#94a3b8" stroke-dasharray="4,4"/>\n  <circle cx="220" cy="75" r="4.5" fill="#dc2626"/>\n  <text x="74" y="79" text-anchor="end" font-size="11" font-weight="bold" fill="#dc2626">fs,max</text>\n  <text x="74" y="114" text-anchor="end" font-size="11" font-weight="bold" fill="#16a34a">fk</text>\n  <text x="220" y="232" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">F = fs,max</text>\n  <text x="145" y="198" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Statik Bölge</text>\n  <text x="145" y="211" text-anchor="middle" font-size="10" fill="#475569">(Durgun: fs = F, açı 45°)</text>\n  <text x="320" y="198" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Kinetik Bölge</text>\n  <text x="320" y="211" text-anchor="middle" font-size="10" fill="#475569">(Hareketli: fk sabit)</text>\n  <rect x="460" y="55" width="215" height="165" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="567" y="78" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">Grafik Okuma Kuralları</text>\n  <text x="472" y="102" font-size="10.5" fill="#334155">• Statik bölgede eğim = tan(45°) = 1</text>\n  <text x="472" y="122" font-size="10.5" fill="#334155">• F &lt; fs,max iken cisim durur ve</text>\n  <text x="480" y="138" font-size="10.5" font-weight="bold" fill="#854d0e">sürtünme kuvveti F kadardır!</text>\n  <text x="472" y="160" font-size="10.5" fill="#334155">• F &gt; fs,max olunca cisim ivmelenir:</text>\n  <text x="480" y="178" font-size="10.5" font-weight="bold" fill="#166534">F_net = F - fk = m · a</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SÜRTÜNME KUVVETİNİN ÖZELLİKLERİ VE GÜNLÜK HAYAT ETKİLERİ</text>\n  <rect x="25" y="50" width="205" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="127" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Bağlı Olduğu Değişkenler</text>\n  <text x="40" y="103" font-size="11" fill="#334155">• Sürtünen yüzeylerin cinsine</text>\n  <text x="48" y="120" font-size="10.5" fill="#475569">(pürüzlülük / k katsayısı) bağlıdır.</text>\n  <text x="40" y="143" font-size="11" fill="#334155">• Yüzeyin dik tepki kuvvetine</text>\n  <text x="48" y="160" font-size="10.5" fill="#475569">(N) doğru orantılı bağlıdır.</text>\n  <text x="40" y="185" font-size="10.5" font-weight="bold" fill="#1e40af">• Temas yüzey alanının (S)</text>\n  <text x="48" y="202" font-size="10.5" font-weight="bold" fill="#1e40af">büyüklüğüne BAĞLI DEĞİLDİR.</text>\n  <rect x="247" y="50" width="205" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Olumlu Etkileri (Avantaj)</text>\n  <text x="262" y="103" font-size="11" fill="#334155">• Yürüme ve koşabilme</text>\n  <text x="262" y="125" font-size="11" fill="#334155">• Araçların güvenli fren yapması</text>\n  <text x="262" y="147" font-size="11" fill="#334155">• Kalemle yazı yazabilme ve</text>\n  <text x="270" y="164" font-size="10.5" fill="#475569">cisimleri elde tutabilme</text>\n  <text x="262" y="186" font-size="11" fill="#334155">• Paraşütle güvenli iniş</text>\n  <text x="262" y="208" font-size="11" fill="#334155">• Çivi ve vidaların tutunması</text>\n  <rect x="470" y="50" width="205" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="572" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Olumsuz Etkileri (Dezavantaj)</text>\n  <text x="485" y="103" font-size="11" fill="#334155">• Makine parçalarının aşınması</text>\n  <text x="485" y="125" font-size="11" fill="#334155">• Mekanik enerjinin ısıya</text>\n  <text x="493" y="142" font-size="10.5" fill="#475569">dönüşerek kaybolması (verim düşer)</text>\n  <text x="485" y="166" font-size="11" fill="#334155">• Azaltma Yöntemleri:</text>\n  <text x="493" y="184" font-size="10.5" fill="#475569">Yağlama, bilye/rulman kullanımı,</text>\n  <text x="493" y="201" font-size="10.5" fill="#475569">aerodinamik tasarım, tekerlek.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
